#!/usr/bin/env python3
import sys


def solve(N, C):
    cnt = 0
    i = 0
    j = N - 1
    while i < N and j >= 0:
        while True:
            if C[i] == "W":
                break
            i += 1
            if i >= N:
                break
        while True:
            if C[j] == "R":
                break
            j -= 1
            if j < 0:
                break
        if i >= j:
            break
        else:
            cnt += 1
            i += 1
            j -= 1
    print(cnt)
    return


# Generated by 1.1.7.1 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    N = int(next(tokens))
    S = next(tokens)
    C = [S[i] for i in range(N)]
    solve(N, C)

if __name__ == '__main__':
    main()